227	    private SummaryResponse toSummaryResponse(OrderSummary summary) {
228	        SummaryResponse response = new SummaryResponse();
229	        response.setProductsSubtotal(summary.getProductsSubtotal());
230	        response.setCouponDiscount(summary.getCouponDiscount());
231	        response.setShippingCost(summary.getShippingCost());
232	        response.setDeliveryDays(summary.getDeliveryDays());
233	        response.setInsurance(summary.getInsurance());
234	        response.setPaymentAdjustment(summary.getPaymentAdjustment());
235	        response.setFinalTotal(summary.getFinalTotal());
236	        response.setInstallments(summary.getInstallments());
237	        response.setInstallmentAmount(summary.getInstallmentAmount());
238	        response.setNextPurchaseCredit(summary.getNextPurchaseCredit());
239	        response.setGift(summary.getGift());
240	        return response;
241	    }
242	
243	    private OrderResponse toOrderResponse(Order order) {
244	        OrderResponse response = new OrderResponse();
245	        response.setId(order.getId());
246	        response.setStatus(order.getStatus());
247	        response.setCreatedAt(order.getCreatedAt());
248	        response.setSummary(toSummaryResponse(order.getSummary()));
249	        response.setTrackingCode(order.getTrackingCode());
250	
251	        List<OrderResponse.ItemResponse> items = new ArrayList<>();
252	        for (OrderItem item : order.getItems()) {
253	            items.add(new OrderResponse.ItemResponse(item.getSku(), item.getQuantity()));
254	        }
255	        response.setItems(items);
256	
257	        return response;
258	    }
259	}
