286	    public QuoteResult getQuote(String zipCode, BigDecimal weightKg, String service) {
287	        try {
288	            int weightGrams = weightKg.multiply(new BigDecimal("1000")).intValue();
289	
290	            String url = String.format("/v2/quote?zip=%s&weight_g=%d&service=%s",
291	                    zipCode, weightGrams, service);
292	
293	            TransLogResponse response = restClient.get()
294	                    .uri(url)
295	                    .retrieve()
296	                    .body(TransLogResponse.class);
297	
298	            if (response == null) {
299	                return QuoteResult.unavailable();
300	            }
301	
302	            if (response.error != null) {
303	                if ("ZIP_NOT_SERVED".equals(response.error)) {
304	                    return QuoteResult.notServed();
305	                }
306	                return QuoteResult.unavailable();
307	            }
308	
309	            if (response.priceCents == null || response.etaHours == null) {
310	                return QuoteResult.unavailable();
311	            }
312	
313	            BigDecimal price = new BigDecimal(response.priceCents)
314	                    .divide(new BigDecimal("100"), 2, RoundingMode.HALF_EVEN);
315	
316	            int days = (int) Math.ceil(response.etaHours / 24.0);
317	
318	            return QuoteResult.success(price, days);
319	
320	        } catch (Exception e) {
321	            return QuoteResult.unavailable();
322	        }
323	    }
